Let $r$ and $k$ be integers with $0 \leq k < r$. Then
    \[
    \sg(R_{r, r}^k)=
    \begin{cases}
        0& r \text{ is even or }k<r-1,\\
        1& r\in \{3,5\}, \, r \text{ is odd, and } k = r-1,\\
        2& \text{otherwise.}
    \end{cases}    
    \]

For $r \geq 7$ we have \[\sg(R_{r,r-1}^k)=
    \begin{cases}
    3& k=r-2 \text{ and } r \text{ odd},\\
    1& \text{otherwise.}
    \end{cases}\]
Also, $\sg(R^1_{3, 2}) = \sg(R^3_{5, 4}) = 3$ and $\sg(R^2_{4, 3}) = 2$ and $\sg(R^4_{6, 5} )= 5$. All other rectairs have Sprague-Grundy value $1$.

\label{conj:SIT_free_GAS}
Consider the SIT-free model obtained from~\eqref{eq:model_I} by setting
$S(t)\equiv0$, with $\zeta>0$ and $\delta_L>0$. Suppose that $\Rq>1$ and
$\KE>\KE^{\ast}$, and let $X_-^{**}$ and $X_+^{**}$ denote, respectively, the
Allee equilibrium and the natural equilibrium of the SIT-free model. Define the
positive wild-population invariant subspace
\begin{equation*}
\Omega_{\mathrm{sf}}
=
\bigl\{(E,L,P,F_u,F_{mw},F_{ms},M_w,M_s)\in\Omega:
E,L,P,F_u,F_{mw},M_w>0,\ F_{ms}=M_s=0\bigr\}.
\end{equation*}
Let
\begin{equation*}
\mathcal{B}_0
:=
\bigl\{X_0\in\Omega_{\mathrm{sf}}:
\lim_{t\to\infty}X(t;X_0)=\mathcal E_0\bigr\}
\end{equation*}
denote the set of positive wild-population initial states whose solutions
converge to the mosquito-free equilibrium $\mathcal E_0$, and let
\begin{equation*}
\mathcal{W}^s_+(X_-^{**})
:=
\bigl\{X_0\in\Omega_{\mathrm{sf}}:
\lim_{t\to\infty}X(t;X_0)=X_-^{**}\bigr\}
\end{equation*}
denote the stable set of the Allee equilibrium in $\Omega_{\mathrm{sf}}$.
Finally, let $\mathcal{P}_+$ be the connected component containing $X_+^{**}$
of the forward-invariant set
\begin{equation*}
\Omega_{\mathrm{sf}}\setminus
\bigl(\mathcal{B}_0\cup\mathcal{W}^s_+(X_-^{**})\bigr).
\end{equation*}
Then the natural equilibrium $X_+^{**}$ is globally asymptotically stable
relative to $\mathcal{P}_+$; that is, $\mathcal{P}_+$ is positively invariant,
$X_+^{**}$ is Lyapunov stable relative to $\mathcal{P}_+$, and every solution
with initial condition in $\mathcal{P}_+$ satisfies
$\lim_{t\to\infty}X(t)=X_+^{**}$.

\label{con:Moss}
Fix an integer $k\geq 1$. For all sufficiently large $n$, there exists a family $\cF\subseteq \binom{[2n]}{n}$ such that:

\begin{enumerate}
    \item[(i)] $\cF$ has maximum possible size subject to containing no complementary pair; that is,
    \[
    |\cF|=\frac{1}{2}\binom{2n}{n}.
    \]
    \item[(ii)] $\cF$ contains no balanced subfamily of size $2,4,\ldots,2k$.
    \item[(iii)] $\cF$ contains a balanced subfamily of size $2k+2$.
\end{enumerate}

\label{lconj}
For fixed $m>1$, for all fixed $k\in\N$, we have 
$$\lim_{n\rightarrow \infty} \frac{\#\SCD(L(m,n))}{k^n} = \infty.$$

\label{mconj}
For all fixed $k\in\N$, we have 
$$\lim_{n\rightarrow \infty} \frac{\#\SCD(M(n))}{k^n} = \infty.$$

\label{conj:subquartic}
Every connected graph of maximum degree at most four satisfies
$\mustar(G) \le H(G)$.

\label{conj:s^star = 1}
For $d^\iota < k < o(d)$ with $s^\star=1$, \Cref{alg:sparse-warm-up} succeeds with sample complexity $n=\tilde O(k)$.
Furthermore, the same guarantee applies even without perturbing the weights.

\label{con:vizing}
For all graphs $G$ and $H$, we have
$$\gamma(G\square H)\ge \gamma(G)\gamma(H).$$

Let $X,Y$ be compact metric spaces with finite shape dimension. Let $\mathfrak{a}: cX\rightarrow cY$ be a coarse map. Assume that $M_{X}$ has $t\in \mathbb{N}$ ends. Let $[\tau_{1}],\dots,[\tau_{t}]\in \pi_{0}^{c}(cX)$ be such that $\{\theta[\tau_{1}],\dots, \theta[\tau_{t}]\}$ are proper homotopy classes of proper rays in $M_{X}$ which represent these ends. Assume that for all $\tau\in \{\tau_{1},\dots, \tau_{t}\}$, there is an isomorphism on coarse homotopy groups $\mathfrak{a}:\pi_{n}^{c}(cX,\tau)\rightarrow \pi_{n}^{c}(cY,\mathfrak{a}\tau)$ for all $n\geq 0$. Then there exists a $l\in \mathbb{N}$ such that $\psi:=(is_{l}\mathfrak{a}R)^{\sim}$ induces an isomorphism 
\begin{align*}
b\circ \psi: \pi_{n}^{e}(M_X,\widetilde{i\tau}) \rightarrow \pi_{n}^{e}(M_Y,\widetilde{is_{l}\mathfrak{a}\tau}) 
\end{align*} 
for all $n\geq 0$ and all $\tau$. \\

If $\psi$ additionally induces an isomorphism on the ends of $M_{X},M_{Y}$, then $\mathfrak{a}$ is a coarse homotopy equivalence.

Let $n\in \mathbb{N}_{0}$. There is an isomorphism between $\pi^c_{n}(X,\omega)$ and the group (or pointed set) of base ray preserving coarse homotopy classes of base ray preserving coarse maps $f: (c'S^{n},c\{x_0\})\rightarrow (X,\omega)$, where 
\begin{align*}
c'S^n=\{(hx,h)\in \mathbb{R}^{n+1} \times [0,\infty)\,|\, x \in S^n, h\in [0,\infty)\}
\end{align*}

(The Hurewicz map) \label{hurewicz} Let $(X,d)$ be a proper metric space and $n\in \mathbb{N}_{0}$. There is a natural morphism 
\begin{align*}
\mathcal{H}: \pi_{n}^{c}(X)\rightarrow H\mathcal{X}_{n+1}(X)
\end{align*}
such that the diagram 


\begin{figure}[H]
\centering
\begin{tikzcd}
&\pi_{n}^{c}(X) \arrow{r}{\mathcal{H}} \arrow{d}{\cong}
&H\mathcal{X}_{n+1}(X)  \arrow{d}{\mathcal{A}}
  \\
&\varinjlim_{h\in \mathbb{N}} \pi^{e}_{n}(|\mathcal{U}_{h}|) \arrow{r}{\varphi}
&\varinjlim_{h\in \mathbb{N}} H^{lf}_{n+1}(|\mathcal{U}_{h}|) 
\end{tikzcd}
\end{figure}
commutes.

\label{shapeex} Let $Y$ be a compact Hausdroff space. Let $(Y_{i})_{i\in \mathbb{N}}$ be a decreasing family of closed subspaces of $Y$. We consider the set-theoretic intersection $\cap_{i\in \mathbb{N}} Y_{i}$ in $Y$ with the subspace topology. We have an exact sequence
\begin{align*}
0\rightarrow {\lim_{i\in \mathbb{N}}}^{1} H\mathcal{X}_{n+1}\mathcal{O}(Y_{i}) \rightarrow H\mathcal{X}_{n}\mathcal{O} (\cap_{i\in \mathbb{N}} Y_{i}) \rightarrow  \lim_{i\in \mathbb{N}} H\mathcal{X}_{n}\mathcal{O}(Y_{i}) \rightarrow 0
\end{align*}
for $n\in \mathbb{N}_{0}$.

Let $E:\mathbf{BornCoarse}\rightarrow \mathbf{C}$ be a coarse homology theory, and let $X$ be a uniform bornological coarse space. Assume:
 \begin{enumerate}
 \item $\mathbf{C}$ is complete. 
 \item $E$ is additive. 
\end{enumerate}
Then we have an equivalence 
 \begin{align*}
 \colim_{\alpha} (E(\ast) \wedge \Sigma_{+}^{\infty})^{lf}(C(i_{\alpha}))\simeq E\mathcal{O}^{\infty}(X)
 \end{align*}

\label{hardylittewood}
Let $h_1,h_2,\ldots,h_k$ be distinct positive even integers such that the numbers of the sequence $\mathbb{P}_k=(p,p+h_1,\ldots,p+h_k)$ do not form a complete residue class with respect to any prime and let
\begin{align}\label{generalisedprimecountingfunction}
\pi_k(x)=\#\{p\leq x: p,p+h_1,\ldots,p+h_k\in\mathbb{P}\}.   
\end{align}
Then
\begin{align*}
\pi_k(x)
\sim C_k\int_{2}^{x}\frac{dt}{\log^{k+1}t},
\end{align*}
where
\begin{align}\label{ktupleconstant}
C_k
=2^k\prod_{\substack{p\in\mathbb{P}\\p\;\mathrm{odd}}}\frac{1-\frac{w(p;h_1,\ldots,h_k)}{q}}{\left(1-\frac{1}{p}\right)^{k+1}},
\end{align}
and $w(p;h_1,\ldots,h_k)$ denotes the number of distinct residues of $0,h_1,\ldots,h_k$ mod $p$.

There is no known sieve method that can prove that
\begin{align*}
\lim_{Q\to\infty} \Delta_Q(x)=0.    
\end{align*}

\label{conj1}
    Consider any prime number $p > 2$ and any $p$-group $G$. Then for each $G$-group $P$ there exists a $G$-central series $C_i$, $0\leq i\leq N$ of $P$ such that:\begin{enumerate}
        \item $C_0 = P$, $C_1 = \gamma_2^G(P)$, $C_N = \{e\}$,
        \item $\log_p[C_i : C_{i+1}]\leq \mathcal{M}^G(P) - i + 1$, $\forall 1\leq i\leq N - 1$.
    \end{enumerate}

\label{conjecture}
    Let $W$ be a finite Coxeter group and $u,v\in W$. Then
        $$T_L(u\jo v)=\overline{T_L(u)\cup T_L(v)}.$$

\label{conj:sharp-PES-threshold}
In the four-dimensional critical regime, the sharp logarithmic interaction
constant should yield the threshold
\begin{equation}
        M_*=\frac{64\pi^2\tau}{\chi}.
\label{conjectured-critical-mass}
\end{equation}
Equivalently, one expects \(\mathcal F_{\mathrm{PES}}\) to be bounded below on
\(\mathcal A_M(\Omega)\) for \(M<M_*\), to lose compactness at \(M=M_*\), and
to be unbounded below for \(M>M_*\).  This statement is conjectural unless the
corresponding sharp \(K_\tau\)-adapted logarithmic HLS/Adams inequality is
proved.

Let \((u,p)\) be a suitable weak solution and let \((0,0)\) have a non-CKN dyadic branch:
\[
    \Psi(r_n)>\eps_{\CKN}
    \qquad\text{for all sufficiently large } n.
\]
Then there exist relative filter scales \(\ell_n\in[\ell_-,\ell_+]\subset(0,1)\), a subsequence, and a constant \(c>0\) such that
\begin{equation}
    \Vort_{n,\ell_n}
    +
    \Press^{\act}_{n}
    +
    \Flux^{\absop}_{n,\ell_n}
    \ge c.
\end{equation}

Whenever $G$ is either $T$ or $\mathbb{Z}_2$,  there exists an equivariant Milnor map
\begin{equation}    
\mu^{G^k}: \Omega^{U,G^k}_{2*} \to 
\Omega^{O,\mathbb{Z}_2^k}_{*}
\end{equation}
reducing the dimension by a half, 
defined as the real points of smooth complex generators,
which is moreover surjective.

Assume the Riemann Hypothesis and that the non-trivial zeros $\rho = \tfrac{1}{2} + i \gamma$ of $\zeta(s)$ are simple. Then
\begin{equation*}
\sum_{0 < \gamma \le T} \left| \frac{\zeta(2\rho)}{\zeta'(\rho)} \right|^2 \sim \frac{T}{2\pi}
\end{equation*}
as $T \to \infty$.

Assume the Riemann Hypothesis and that the non-trivial zeros of $\zeta(s)$ are simple. Then
\begin{equation*}
\sum_{0 < \gamma \le T} \frac{1}{|\zeta'(\rho)|^2} \sim \frac{3}{\pi^3}T
\end{equation*}
as $T \to \infty$.

Let $\Sigma\subset \R^d$ be a compact set which is not a removable set for $\Delta$ in $L^2(\R^d)$. Then, there exist a self-adjoint extension  of $\Delta|_{C_c^\infty(\R^d\backslash \Sigma)}$ in $L^2(\R^d)$, $\widetilde{\Delta}$, and  a measure valued process $\left\{\mathcal{X}_t\right\}_{t\geq 0}$ such that  \begin{align*}
\mathtt{E}_{\delta_x}[\mathcal{X}_t(u_0)]=\widetilde{u}(t,x)
\end{align*}
for any $t>0$ and any $x\in \R^3\backslash\Sigma$, where $\widetilde{u}$ is the solution to \begin{align*}
\partial_t u=\frac{1}{2}\widetilde{\Delta}u,\quad u(0,x)=u_0(x).
\end{align*}

\label{Conj}
For any integer $t \geq 3$ and $\alpha \in [0,1]$,                         
let the random variables $\vE^*$, $\vB^*$, $\vX_1$, and $\vX_2$ be independent with distributions
\begin{equation*}
    \vE^* \sim \Po(r^*), \qquad \vB^* \sim \Po(\alpha r^*), \qquad \vX_1, \vX_2 \sim \Po((1-\alpha)r^*).
\end{equation*}
Define the maximum of $\vX_1$ and $\vX_2$ to be $\vM^* = \max\{\vX_1, \vX_2\}$. Let the probabilities $q(r^*)$ and $p(r^*,\alpha)$ be given by
\begin{equation*}
    q(r^*) = \Pr(\vE^* \leq t-1) \quad \text{and} \quad p(r^*,\alpha) = \Pr(\vB^* + \vM^* \leq t-1).
\end{equation*}
Then, for all $c>c_{\mathrm{inf}}^{\mathrm{TGT}}$, the function
\begin{align}
    \alpha \mapsto 1 - \alpha + c \bc{q(r^*) \log\bcfr{p(\alpha)}{q(r^*)} + (1-q(r^*)) \log\bcfr{1-2q(^*)+p(r^*,\alpha)}{1-q(r^*)}} 
\end{align}
is maximised in $\alpha=0$.

\label{conj:main} If $G$ has bounded degrees and satisfies $\CD(0,\infty)$, then $G$ has polynomial growth. More precisely,
\begin{eqnarray}
\label{def:poly}
\forall x\in V,\quad \forall r\in \dN,\quad \# B(x,r) & \le & r^D,
\end{eqnarray}
where the constant $D<\infty$  depends only on the maximum degree.

\label{conj1}
There holds
\begin{equation}\label{conj1-id}
\sum_{n\geq 0} a_2''(n) q^n
=\fr{q}{1-q^2}+\fr{1}{1+q}\sum_{n\geq 0} \chi(n) q^{\binom{n+1}{2}+1},
\end{equation}
where
\[
\chi(n)
=\begin{cases}
-1 &\ \text{if\ }n\equiv 0,1\Mod{4}, \\
1 &\ \text{if\ }n\equiv 2,3\Mod{4}.
\end{cases}
\]

\cite{bhargava2023rank}\label{Conj: directed bipartite graph}
Consider constants $0<v<1$ and $ \frac{1}{p}<\alpha \leq 1$ and a finite abelian $p$-group $G$.
Then
\[
\lim_{n \rightarrow \infty} 
\PPb{(S_{\vec G_{\alpha}(n,v)})_p \cong G} 
=P_{\infty,\frac{1}{p}}(G).
\]

\label{conj:Nivat}
  Let $\eta\in\mathcal A^{\mathbb Z^2}$.  If $P_\eta(k,n)\le kn$ for some
  $k,n\in\mathbb N$, then $\eta$ is periodic.

(Hodge conjecture)
\label{Hgconj}
Let $Y$ be a smooth projective algebraic variety over $\mathbb{C}$, let $j \geq 0$ be an integer, and suppose that $c \in H^{2j}_{B}(Y, \mathbb{Q}(j))$ is a class which lies inside the middle Hodge summand $H^{j,j} \subset H^{2j}_{B}(Y, \mathbb{C})$. Then $c$ is in the $\mathbb{Q}$-span of the algebraic cycle classes.

(Grothendieck Period Conjecture)
\label{Gperconj}
Let $Y$ be a smooth projective variety over a number field $K \subset \mathbb{C}$ and $j$ a natural number. Then the transcendence degree (over $\Q$) of the field generated by the period matrix for the Betti-de Rham period morphism $H^j(Y_{\mathbb{C}}, \mathbb{Q}) \otimes \mathbb{C} \xrightarrow{\sim} H^j_{\operatorname{dR}}(Y) \otimes_{K} \mathbb{C}$ is equal to the dimension of the Mumford--Tate group of the Hodge structure on $H^j(Y_{\mathbb{C}}, \mathbb{Q})$.

(Tate conjecture)
\label{Tateconj}
