The diameter for $k$-cycles 2-Different coset graph with central state of length $n$ is
\begin{equation*}

    d_k(n) = \Big\lfloor \frac{2n + k(k-4)}{2k-2} \Big\rfloor + 1 - \mathbb I[k \text{ is odd}, 2 \leqslant n \mod (k - 1) \leqslant (k-1)/2]
\end{equation*}

We conjecture that the diameter for $k$-cycles 3-Different coset graph with central state of length $n$ equals to
\begin{equation}
    d_k(n) = \left\lfloor \frac{2n + c_k}{k-1} \right\rfloor,\quad
    k \geqslant 2, \quad n \geqslant N_k,
    \label{eq:3diff-formula}
\end{equation}
where $c_2 = -3$, $c_3 = -1$, and for $k\geqslant 4$ the offset $c_k$ is a quadratic function of $k$ whose form depends on the parity of $k$:




\begin{equation}
    c_k = \begin{cases}
        \dfrac{k(k-1)}{2} - 5 & \text{if } k \text{ is even}, \\[6pt]
        \dfrac{(k-1)^2}{2} - 4 & \text{if } k \text{ is odd.}
    \end{cases}
    \label{eq:ck-formula}
\end{equation}

The diameter for $k$-cycles L-Different coset graph with central state of length $n$ is
\begin{equation*}
    d_k(n) = \Big\lfloor \frac{Ln}{2(k-1)} + c_k \Big\rfloor +r_k(n),
\end{equation*}
where $c_k = O(k)$, $r_k(n)$ is a "small" remainder (possibly $O(1)$).

For even $k \ge 6$, we conjecture that, for all sufficiently large $n$, the sequence $s_k(n)$ follows a single periodic pattern of odd values. Let
\begin{equation*}
    C_k = \frac{k(k-1)}{2} - 5,
    \qquad
    m = (2n + C_k) \bmod (k-1).
\end{equation*}
Then
\begin{equation*}
    s_k(n) = m + \big(1 - (m \bmod 2)\big)
    + \left\lfloor \frac{1}{|m - (k-2)| + 1} \right\rfloor
    + 2\left\lfloor \frac{1}{|m - (k-3)| + 1} \right\rfloor.
\end{equation*}

For odd $k \ge 7$, we conjecture that, for all sufficiently large $n$, the sequence $s_k(n)$ follows a two-half alternating periodic pattern, where each half has length
\begin{equation*}
    H = \frac{k-1}{2}.
\end{equation*}
Let
\begin{equation*}
    C_k = \frac{(k-1)^2}{2} - 4,
    \qquad
    m = \left(n + \frac{C_k}{2} + H\right) \bmod (k-1).
\end{equation*}
Define the two correction locations by
\begin{equation*}
    (m_{\mathrm{origin}}, m_{\mathrm{spike}}) =
    \begin{cases}
        (H,\, 2H-1), & k \equiv 1 \pmod{4},\\
        (0,\, H-1), & k \equiv 3 \pmod{4}.
    \end{cases}
\end{equation*}
Then
\begin{equation*}
    s_k(n) = m + \big(1 - (m \bmod 2)\big)
    + \left\lfloor \frac{1}{|m - m_{\mathrm{origin}}| + 1} \right\rfloor
    + 2\left\lfloor \frac{1}{|m - m_{\mathrm{spike}}| + 1} \right\rfloor.
\end{equation*}

